%% examples/web_support_example.pl
%%
%%  Example generated web program that uses web_support.pl (Stage 11).
%%
%%  This file shows how a program generated by vetusiapl2webpl looks when
%%  it loads helpers from web_support.pl rather than relying on inlined
%%  helper definitions.  It is the direct equivalent of output_example.pl
%%  but with a :- use_module(web_support). directive in place of the
%%  inlined helper block.
%%
%%  Input program:  examples/input_example.pl
%%    main :-
%%        writeln('Enter your name:'),
%%        read_string(user, "\n", "\r", _, Name),
%%        writeln('Enter your age:'),
%%        read_string(user, "\n", "\r", _, Age),
%%        format("Hello, ~w! You are ~w years old.~n", [Name, Age]).
%%
%%  To run:
%%    swipl examples/web_support_example.pl
%%  Then open http://localhost:8080 in your browser.

:- use_module(library(http/thread_httpd)).
:- use_module(library(http/http_dispatch)).
:- use_module(library(http/html_write)).
:- use_module(library(http/http_parameters)).
:- use_module(library(http/http_header)).

%% --------------------------------------------------
%% Runtime helpers loaded from web_support.pl (Stage 11)
%% --------------------------------------------------

:- use_module(web_support).

:- http_handler(root(.), step_0, []).
:- http_handler(root(step_1), step_1, [method(post)]).
:- http_handler(root(step_2), step_2, [method(post)]).

vetusia_server(Port) :-
    http_server(http_dispatch, [port(Port)]).

:- initialization(main, main).

main :-
    vetusia_server(8080).

%% step_0 — display the first prompt and collect the user's name.
step_0(_Request) :-
    reply_html_page(
        title('Step 0'),
        [ form([method=post, action='/step_1'],
              [ p('Enter your name:'),
                input([type=text, name='Name', autofocus=autofocus]),
                input([type=submit, value='Next'])
              ])
        ]).

%% step_1 — receive the name, display the second prompt, collect age.
step_1(Request) :-
    ws_request_param(Request, 'Name', Name),
    reply_html_page(
        title('Step 1'),
        [ form([method=post, action='/step_2'],
              [ input([type=hidden, name='Name', value=Name]),
                p('Enter your age:'),
                input([type=text, name='Age', autofocus=autofocus]),
                input([type=submit, value='Next'])
              ])
        ]).

%% step_2 — receive name and age, display the final greeting.
step_2(Request) :-
    ws_request_params(Request, ['Name'=Name, 'Age'=Age]),
    html_page_header('Result'),
    html_writeln(Name),
    html_writeln(Age),
    format("Hello, ~w! You are ~w years old.~n", [Name, Age]),
    html_page_footer.
